coding.solution:
#include <iostream>

using std::cout;
using std::endl;

int main()
{
    int iNumber1 = 10;
    int iNumber2 = 20;

    int* pNumber1 = &iNumber1;
    int* pNumber2 = &iNumber2;

    cout << "Before: iNumber1 = " << iNumber1 << ", iNumber2 = " << iNumber2 << endl;

    int iTemp = *pNumber1;
    *pNumber1 = *pNumber2;
    *pNumber2 = iTemp;

    cout << "After: iNumber1 = " << iNumber1 << ", iNumber2 = " << iNumber2 << endl;

    return 0;
}
